import 'package:flutter/material.dart';
import '../../models/complaint_model.dart';
import '../../repositories/complaint_repository.dart';
import '../../services/api/api_client.dart';
import '../routes/app_routes.dart';
import '../theme/app_colors.dart';
import '../widgets/citizen_shell.dart';

class MyComplaintsScreen extends StatefulWidget { const MyComplaintsScreen({super.key}); @override State<MyComplaintsScreen> createState()=>_MyComplaintsScreenState(); }
class _MyComplaintsScreenState extends State<MyComplaintsScreen>{ List<ComplaintModel> items=[]; bool loading=true; String? error; String filter='All';
 Future<void> _load() async{setState(()=>loading=true);try{items=await RealComplaintRepository(ApiClient()).getMyComplaints();error=null;}catch(e){error=e.toString();}if(mounted)setState(()=>loading=false);}
 @override void initState(){super.initState();_load();}
 List<ComplaintModel> get visible{if(filter=='All')return items;return items.where((c){if(filter=='Pending')return [ComplaintStatus.submitted,ComplaintStatus.verification,ComplaintStatus.verified].contains(c.status);if(filter=='In Progress')return [ComplaintStatus.assigned,ComplaintStatus.workerAccepted,ComplaintStatus.inProgress,ComplaintStatus.workerCompleted,ComplaintStatus.rework].contains(c.status);return c.status==ComplaintStatus.resolved||c.status==ComplaintStatus.closed;}).toList();}
 @override Widget build(BuildContext context)=>CitizenShell(index:1,title:'My Registered Complaints',onRefresh:_load,child:loading?const Center(child:CircularProgressIndicator()):error!=null?Center(child:Padding(padding:const EdgeInsets.all(24),child:Text(error!))):ListView(padding:const EdgeInsets.fromLTRB(16,8,16,28),children:[const Text('Track status, worker progress & municipal verification.',style:TextStyle(fontSize:10,color:AppColors.textSecondary)),const SizedBox(height:12),const TextField(decoration:InputDecoration(hintText:'Search by ID, category, or location',prefixIcon:Icon(Icons.search_rounded,size:18),contentPadding:EdgeInsets.symmetric(vertical:10),filled:true,fillColor:Colors.white,border:OutlineInputBorder(borderRadius:BorderRadius.all(Radius.circular(12)),borderSide:BorderSide(color:AppColors.cardBorder)))),const SizedBox(height:10),SingleChildScrollView(scrollDirection:Axis.horizontal,child:Row(children:['All','Pending','In Progress','Resolved'].map((x)=>Padding(padding:const EdgeInsets.only(right:7),child:ChoiceChip(label:Text(x,style:TextStyle(fontSize:9,fontWeight:FontWeight.w700,color:filter==x?Colors.white:AppColors.textSecondary)),selected:filter==x,showCheckmark:false,selectedColor:const Color(0xFF1769FF),backgroundColor:Colors.white,side:const BorderSide(color:AppColors.cardBorder),onSelected:(_)=>setState(()=>filter=x)))).toList())),const SizedBox(height:12),if(visible.isEmpty)const Padding(padding:EdgeInsets.only(top:60),child:Center(child:Text('No complaints in this category.',style:TextStyle(color:AppColors.textSecondary)))) else ...visible.map(_card)]));
 Widget _card(ComplaintModel c)=>InkWell(onTap:()=>Navigator.pushNamed(context,AppRoutes.complaintDetails,arguments:c.id).then((_ )=>_load()),child:Container(margin:const EdgeInsets.only(bottom:10),padding:const EdgeInsets.all(12),decoration:BoxDecoration(color:Colors.white,borderRadius:BorderRadius.circular(14),border:Border.all(color:AppColors.cardBorder)),child:Column(crossAxisAlignment:CrossAxisAlignment.start,children:[Row(children:[const Icon(Icons.construction_rounded,size:16,color:Color(0xFF1E2944)),const SizedBox(width:5),Text('#${c.id}',style:const TextStyle(fontSize:8,color:AppColors.textTertiary)),const Spacer(),_tag(c.priority.name.toUpperCase(),const Color(0xFFF3B64C)),const SizedBox(width:5),_tag(_status(c.status),const Color(0xFF4A8DEB))]),const SizedBox(height:6),Text(_cat(c.category),style:const TextStyle(fontSize:13,fontWeight:FontWeight.w800)),const SizedBox(height:4),Text(c.description,maxLines:2,overflow:TextOverflow.ellipsis,style:const TextStyle(fontSize:10,color:AppColors.textSecondary,height:1.35)),const SizedBox(height:6),Row(children:[const Icon(Icons.location_on_outlined,size:12,color:AppColors.textTertiary),const SizedBox(width:4),Expanded(child:Text(c.address,maxLines:1,overflow:TextOverflow.ellipsis,style:const TextStyle(fontSize:9,color:AppColors.textSecondary))),const Icon(Icons.chevron_right_rounded,size:17,color:AppColors.textTertiary)]),const SizedBox(height:7),Row(children:[const Icon(Icons.access_time_outlined,size:11,color:AppColors.textTertiary),const SizedBox(width:4),Text('${c.createdAt.day.toString().padLeft(2,'0')} ${_month(c.createdAt.month)} ${c.createdAt.year}',style:const TextStyle(fontSize:8,color:AppColors.textTertiary)),const Spacer(),const Text('VIEW DETAILS  ›',style:TextStyle(fontSize:8,fontWeight:FontWeight.w900,color:Color(0xFF1769FF)))])])));
 Widget _tag(String t,Color c)=>Container(padding:const EdgeInsets.symmetric(horizontal:7,vertical:3),decoration:BoxDecoration(color:c.withValues(alpha:.14),borderRadius:BorderRadius.circular(5)),child:Text(t,style:TextStyle(fontSize:7,fontWeight:FontWeight.w900,color:c)));
 String _cat(IssueCategory c)=>c.name.replaceAll('_',' ').toUpperCase();String _status(ComplaintStatus s)=>s==ComplaintStatus.inProgress?'IN PROGRESS':s==ComplaintStatus.workerCompleted?'WORK COMPLETED':s.name.replaceAll('_',' ').toUpperCase();String _month(int m)=>const ['','Jan','Feb','Mar','Apr','May','Jun','Jul','Aug','Sep','Oct','Nov','Dec'][m];
}
